class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected."""
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        """
        Resolves task dependencies into execution stages (batches).

        :param dependencies: Mapping of task_name -> list of task_names it depends on.
        :return: List of stages, where each stage is a sorted list of task names that can run in parallel.
        :raises CircularDependencyError: If any circular dependency is detected.
        """
        # Collect all unique tasks (both keys and any referenced dependencies)
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        if not all_tasks:
            return []

        # Track remaining unresolved dependencies for each task
        remaining_deps: dict[str, set[str]] = {
            task: set(dependencies.get(task, [])) for task in all_tasks
        }

        # Build reverse adjacency list: dependency -> list of tasks waiting on it
        dependents: dict[str, list[str]] = {task: [] for task in all_tasks}
        for task, deps in remaining_deps.items():
            for dep in deps:
                dependents[dep].append(task)

        # Stage 0 contains all tasks with no dependencies
        current_stage = [task for task, deps in remaining_deps.items() if not deps]

        stages: list[list[str]] = []
        resolved_count = 0

        while current_stage:
            sorted_stage = sorted(current_stage)
            stages.append(sorted_stage)
            resolved_count += len(sorted_stage)

            next_stage: list[str] = []
            for task in sorted_stage:
                for dependent in dependents[task]:
                    remaining_deps[dependent].discard(task)
                    if not remaining_deps[dependent]:
                        next_stage.append(dependent)

            current_stage = next_stage

        if resolved_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected among tasks.")

        return stages
