from typing import Any, Dict, List, Optional, Set


class QuorumCluster:
    def __init__(self, node_ids: list[str]) -> None:
        """
        Initializes cluster state with given unique node IDs.
        Total node count N = len(node_ids). Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids: list[str] = list(node_ids)
        self.n: int = len(self.node_ids)
        self.quorum_threshold: int = (self.n // 2) + 1

        # Per-node key-value store: node_id -> {key: (version, value)}
        self.node_data: dict[str, dict[str, tuple[int, Any]]] = {
            node: {} for node in self.node_ids
        }

        # Network partitions: node_id -> set of reachable node_ids
        self.partitions: dict[str, set[str]] = {
            node: set(self.node_ids) for node in self.node_ids
        }

        self._version_counter: int = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in group_a
        can only talk to group_a, and group_b only to group_b.
        Any nodes not listed are isolated in their own individual partitions.
        """
        set_a = set(group_a)
        set_b = set(group_b)

        new_partitions: dict[str, set[str]] = {}
        for node in self.node_ids:
            if node in set_a:
                new_partitions[node] = set_a
            elif node in set_b:
                new_partitions[node] = set_b
            else:
                new_partitions[node] = {node}

        self.partitions = new_partitions

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        # Restore full connectivity
        all_nodes = set(self.node_ids)
        for node in self.node_ids:
            self.partitions[node] = set(all_nodes)

        # Determine the latest committed state for each key across all nodes
        latest_state: dict[str, tuple[int, Any]] = {}
        for node in self.node_ids:
            for key, (version, val) in self.node_data[node].items():
                if key not in latest_state or version > latest_state[key][0]:
                    latest_state[key] = (version, val)

        # Synchronize all nodes to the latest state
        for node in self.node_ids:
            self.node_data[node] = dict(latest_state)

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write from from_node.
        - Commits and updates state in all nodes within the partition if the partition
          has a STRICT MAJORITY (>= quorum threshold), returning True.
        - Rejects the write if from_node is in a MINORITY partition (< quorum threshold),
          returning False.
        """
        if from_node not in self.partitions:
            return False

        active_partition = self.partitions[from_node]
        if len(active_partition) >= self.quorum_threshold:
            self._version_counter += 1
            entry = (self._version_counter, value)
            for node in active_partition:
                self.node_data[node][key] = entry
            return True

        return False

    def read_value(self, from_node: str, key: str) -> Any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node not in self.node_data:
            return None

        entry = self.node_data[from_node].get(key)
        return entry[1] if entry is not None else None
