import re


def normalize_whitespace(text: str) -> str:
    """Normalizes multiple whitespace characters (spaces, tabs, newlines) into a single space."""
    return re.sub(r"\s+", " ", text).strip()


def mask_string_literals(query: str) -> str:
    """
    Replaces valid string literals with a placeholder '__STR__' so that syntax inspection
    does not trigger false positives on keywords/operators contained within string constants.
    Supports standard SQL single-quoted strings (including '' and \\' escaping) and
    PostgreSQL dollar-quoted strings ($$...$$ or $tag$...$tag$).
    """
    n = len(query)
    i = 0
    out = []

    while i < n:
        # PostgreSQL dollar-quoted strings: $$...$$ or $tag$...$tag$
        if query[i] == "$":
            m = re.match(r"\$([a-zA-Z0-9_]*)\$", query[i:])
            if m:
                tag = m.group(1)
                close_tag = f"${tag}$"
                close_pos = query.find(close_tag, i + len(m.group(0)))
                if close_pos != -1:
                    out.append(" '__STR__' ")
                    i = close_pos + len(close_tag)
                    continue

        # Single-quoted string literals: '...'
        if query[i] == "'":
            start = i
            i += 1
            closed = False
            while i < n:
                if query[i] == "'":
                    if i + 1 < n and query[i + 1] == "'":
                        i += 2  # SQL standard escaped quote ''
                        continue
                    else:
                        i += 1  # Closing quote
                        closed = True
                        break
                elif query[i] == "\\" and i + 1 < n:
                    i += 2  # C-style backslash escape
                else:
                    i += 1
            if closed:
                out.append(" '__STR__' ")
            else:
                # Unclosed string literal: keep trailing content for injection inspection
                out.append(query[start:])
                break
            continue

        out.append(query[i])
        i += 1

    return "".join(out)


def is_safe_sql_query(query: str) -> tuple[bool, str]:
    """
    Analyzes a SQL query string to detect malicious SQL injection signatures
    while allowing legitimate modern SQL syntax, JSON operators, window functions,
    and keywords inside valid string literals.

    Args:
        query (str): The SQL query or injection payload string to inspect.

    Returns:
        tuple[bool, str]: (True, "SAFE") if the query is safe,
                          (False, "REASON") if a malicious signature is detected.
    """
    if not isinstance(query, str) or not query.strip():
        return True, "SAFE"

    # Normalize whitespace for consistent pattern inspection
    norm_query = normalize_whitespace(query)

    # --------------------------------------------------------------------------
    # 1. Obfuscation / Inline Comment Evasion Signatures
    # --------------------------------------------------------------------------
    # MySQL conditional executable comments: e.g., /*!50000SELECT*/, /*!SELECT*/
    if re.search(r"/\*!\d*", norm_query):
        return (
            False,
            "Obfuscation / inline comment evasion detected: MySQL conditional executable comment",
        )

    # Inline comment splitting keywords/identifiers: e.g., UN/**/ION, SEL/**/ECT, 1/**/OR/**/1
    if re.search(r"[a-zA-Z0-9_]/\*.*?\*/[a-zA-Z0-9_]", query, re.DOTALL):
        return (
            False,
            "Obfuscation / inline comment evasion detected: Inline comment token splitting",
        )

    # Null bytes or URL-encoded null byte evasion
    if re.search(r"(?:%00|\x00|\\0)", norm_query, re.IGNORECASE):
        return (
            False,
            "Obfuscation / inline comment evasion detected: Null byte injection",
        )

    # Inline comments concealing blocked keywords
    stripped_comments = re.sub(r"/\*.*?\*/", "", norm_query)
    keyword_pattern = r"(?i)\b(UNION(?:\s+(?:ALL|DISTINCT))?\s*(?:\(\s*)*SELECT|DROP\s+TABLE|EXEC\s+(?:xp_|sp_|cmd)?|pg_sleep)\b"
    if re.search(keyword_pattern, stripped_comments) and not re.search(
        keyword_pattern, norm_query
    ):
        return (
            False,
            "Obfuscation / inline comment evasion detected: Inline comment concealing keywords",
        )

    # --------------------------------------------------------------------------
    # 2. Boolean / Tautology Injection & Comment-Out Auth-Bypass Signatures
    # --------------------------------------------------------------------------
    # Auth-bypass / comment delimiter termination: e.g., admin'--, admin' --, admin' #, admin'/*, admin" --
    if re.search(r"""(?i)(?:^|[\w'"])\s*(?:'|")\s*(?:--|#|/\*)""", norm_query):
        return (
            False,
            "Boolean/Tautology injection detected: Quote followed by comment delimiter",
        )

    # Quote/Paren breakout followed by OR/AND string tautology:
    # e.g., ' OR '1'='1', ' OR '1'='1, " OR "1"="1, ' OR 'a'='a, 1' OR '1'='1, ')) OR (('1'='1
    if re.search(
        r"""(?i)(?:'|"|\)\s*)+\s*(?:OR|AND)\s+(?:\(\s*)*(['"])([^'"\s=<>]+)\1\s*=\s*\1\2(?:\1)?""",
        norm_query,
    ):
        return (
            False,
            "Boolean/Tautology injection detected: Injected string comparison tautology",
        )

    # Quote/Paren breakout followed by numeric tautologies: e.g., ' OR 1=1, " OR 1=1 --, 1' OR 1=1
    if re.search(
        r"""(?i)(?:'|"|\)\s*)+\s*(?:OR|AND)\s+(?:\(\s*)*(\d+)\s*=\s*\1""",
        norm_query,
    ):
        return (
            False,
            "Boolean/Tautology injection detected: Injected numeric comparison tautology",
        )

    # Quote/Paren breakout followed by empty string tautologies: e.g., ' OR ''=', ' OR ""=", ' OR ''=''
    if re.search(
        r"""(?i)(?:'|"|\)\s*)+\s*(?:OR|AND)\s+(?:\(\s*)*(['"])\1\s*=\s*(?:\1\1|\1)""",
        norm_query,
    ):
        return (
            False,
            "Boolean/Tautology injection detected: Empty string comparison tautology",
        )

    # Quote/Paren breakout followed by boolean literal: e.g., ' OR true, " OR true, ') OR true--
    if re.search(
        r"""(?i)(?:'|"|\)\s*)+\s*(?:OR|AND)\s+(?:\(\s*)*true\b""", norm_query
    ):
        return (
            False,
            "Boolean/Tautology injection detected: Injected boolean literal tautology",
        )

    # Standalone OR tautologies: e.g., OR 1=1, OR '1'='1', OR "1"="1", OR 'a'='a', OR true
    if re.search(
        r"""(?i)\bOR\s+(?:(['"])([^'"\s=<>]+)\1\s*=\s*\1\2\1|(\b\d+\b)\s*=\s*\3|true\b)""",
        norm_query,
    ):
        return (
            False,
            "Boolean/Tautology injection detected: Standalone OR tautology",
        )

    # Standalone empty string tautology: OR ''='', OR ""=""
    if re.search(r"""(?i)\bOR\s+(['"])\1\s*=\s*(?:\1\1|\1)""", norm_query):
        return (
            False,
            "Boolean/Tautology injection detected: Standalone empty string tautology",
        )

    # --------------------------------------------------------------------------
    # Structural Query Checks (Evaluated outside legitimate string literals)
    # --------------------------------------------------------------------------
    masked_query = mask_string_literals(norm_query)

    # 3. UNION-Based Data Exfiltration Signatures
    # e.g., UNION SELECT, UNION ALL SELECT, UNION DISTINCT SELECT, UNION(SELECT ...)
    if re.search(
        r"(?i)\bUNION(?:\s+(?:ALL|DISTINCT))?\s*(?:\(\s*)*SELECT\b",
        masked_query,
    ):
        return (
            False,
            "UNION-based data exfiltration detected: UNION SELECT statement",
        )

    # 4. Time-Based Blind Execution Signatures
    # e.g., pg_sleep(), sleep(), benchmark(), WAITFOR DELAY, dbms_pipe.receive_message()
    if re.search(
        r"(?i)\b(?:pg_sleep\s*\(|sleep\s*\(|benchmark\s*\(|waitfor\s+(?:delay|time)\b|dbms_pipe\.receive_message\s*\(|dbms_lock\.sleep\s*\()",
        masked_query,
    ):
        return (
            False,
            "Time-based blind execution detected: Execution delay function",
        )

    # 5. Stacked Query Execution Signatures
    # e.g., ; DROP TABLE, ; EXEC xp_cmdshell, ; DELETE FROM, ; TRUNCATE TABLE
    stacked_cmd_pattern = r"(?i);\s*(?:DROP\s+(?:TABLE|DATABASE|VIEW|INDEX|SCHEMA|PROCEDURE|FUNCTION|TRIGGER|USER|ROLE)|DELETE\s+(?:FROM\s+)?|TRUNCATE\s+(?:TABLE\s+)?|INSERT\s+INTO|UPDATE\s+|EXEC(?:UTE)?\s*(?:\(\s*)?(?:xp_|sp_|cmd|[a-zA-Z0-9_]+)?|ALTER\s+(?:TABLE|DATABASE|USER)|CREATE\s+(?:TABLE|DATABASE|USER)|SHUTDOWN|GRANT|REVOKE|WAITFOR\s+(?:DELAY|TIME))\b"
    if re.search(stacked_cmd_pattern, masked_query):
        return (
            False,
            "Stacked query execution detected: Multiple queries chained with semicolon",
        )

    # Standalone stacked command prefix starting with ';'
    if re.search(
        r"(?i)^\s*;\s*(?:DROP|DELETE|TRUNCATE|INSERT|UPDATE|EXEC|ALTER|CREATE|SHUTDOWN)\b",
        masked_query,
    ):
        return (
            False,
            "Stacked query execution detected: Standalone chained command",
        )

    return True, "SAFE"
