import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    """
    Parses Python source code and uses AST analysis to prune unused imports
    and dead top-level private functions (functions starting with '_').

    Preserves module docstrings, classes, global variable assignments,
    public functions, and returns valid Python code that compiles cleanly.
    """
    tree = ast.parse(source_code)

    def get_import_bound_name(alias: ast.alias, is_from: bool) -> str:
        """Determines the local symbol name bound in scope by an import alias."""
        if alias.asname:
            return alias.asname
        if is_from:
            return alias.name
        # For 'import a.b.c', the root package 'a' is bound locally
        return alias.name.split(".")[0]

    def extract_references(node: ast.AST) -> set[str]:
        """Extracts all referenced symbol names within an AST node."""
        refs: set[str] = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                if isinstance(child.ctx, (ast.Load, ast.Del)):
                    refs.add(child.id)
            elif isinstance(child, (ast.Global, ast.Nonlocal)):
                refs.update(child.names)
            elif isinstance(child, ast.AugAssign):
                if isinstance(child.target, ast.Name):
                    refs.add(child.target.id)
            elif isinstance(child, ast.Assign):
                # Handle exported names in __all__ = ["_helper", ...]
                for target in child.targets:
                    if isinstance(target, ast.Name) and target.id == "__all__":
                        for elt in ast.walk(child.value):
                            if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                                refs.add(elt.value)
            # Handle string forward-reference type annotations
            elif isinstance(child, (ast.AnnAssign, ast.arg)) and isinstance(child.annotation, ast.Constant) and isinstance(child.annotation.value, str):
                try:
                    expr = ast.parse(child.annotation.value, mode="eval")
                    for n in ast.walk(expr):
                        if isinstance(n, ast.Name):
                            refs.add(n.id)
                except Exception:
                    pass
            elif isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and isinstance(child.returns, ast.Constant) and isinstance(child.returns.value, str):
                try:
                    expr = ast.parse(child.returns.value, mode="eval")
                    for n in ast.walk(expr):
                        if isinstance(n, ast.Name):
                            refs.add(n.id)
                except Exception:
                    pass
        return refs

    # Identify candidate top-level private functions (names starting with '_')
    top_level_private_funcs: dict[str, list[ast.AST]] = {}
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
            top_level_private_funcs.setdefault(stmt.name, []).append(stmt)

    # Initial live roots: top-level statements that are NOT candidate private functions and NOT imports
    live_stmts: list[ast.AST] = []
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
            continue
        if isinstance(stmt, (ast.Import, ast.ImportFrom)):
            # Wildcard imports are always treated as live
            if isinstance(stmt, ast.ImportFrom) and any(alias.name == "*" for alias in stmt.names):
                live_stmts.append(stmt)
            continue
        live_stmts.append(stmt)

    # Reachability analysis (BFS) to determine which top-level private functions are called/used
    live_private_func_names: set[str] = set()
    queue: list[str] = []

    for stmt in live_stmts:
        for ref in extract_references(stmt):
            if ref in top_level_private_funcs and ref not in live_private_func_names:
                live_private_func_names.add(ref)
                queue.append(ref)

    while queue:
        curr_name = queue.pop(0)
        for func_node in top_level_private_funcs[curr_name]:
            for ref in extract_references(func_node):
                if ref in top_level_private_funcs and ref not in live_private_func_names:
                    live_private_func_names.add(ref)
                    queue.append(ref)

    # Collect all referenced names across all live roots and reachable private functions
    all_live_references: set[str] = set()
    for stmt in live_stmts:
        all_live_references.update(extract_references(stmt))
    for name in live_private_func_names:
        for func_node in top_level_private_funcs[name]:
            all_live_references.update(extract_references(func_node))

    # AST Transformer to eliminate dead private functions and unused imports
    class DeadCodeCleaner(ast.NodeTransformer):
        def generic_visit_stmt_list(self, stmts: list[ast.stmt], is_module_level: bool = False) -> list[ast.stmt]:
            new_stmts: list[ast.stmt] = []
            for stmt in stmts:
                # Remove unreferenced top-level private functions
                if is_module_level and isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
                    if stmt.name not in live_private_func_names:
                        continue
                    new_stmts.append(self.visit(stmt))
                    continue

                # Prune unused names in 'import ...'
                if isinstance(stmt, ast.Import):
                    kept_aliases = [
                        alias for alias in stmt.names
                        if get_import_bound_name(alias, is_from=False) in all_live_references
                    ]
                    if kept_aliases:
                        stmt.names = kept_aliases
                        new_stmts.append(stmt)
                    continue

                # Prune unused names in 'from ... import ...'
                if isinstance(stmt, ast.ImportFrom):
                    if any(alias.name == "*" for alias in stmt.names):
                        new_stmts.append(stmt)
                        continue
                    kept_aliases = [
                        alias for alias in stmt.names
                        if get_import_bound_name(alias, is_from=True) in all_live_references
                    ]
                    if kept_aliases:
                        stmt.names = kept_aliases
                        new_stmts.append(stmt)
                    continue

                visited = self.visit(stmt)
                if visited is not None:
                    if isinstance(visited, list):
                        new_stmts.extend(visited)
                    else:
                        new_stmts.append(visited)
            return new_stmts

        def visit_Module(self, node: ast.Module) -> ast.Module:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=True)
            return node

        def visit_FunctionDef(self, node: ast.FunctionDef) -> ast.FunctionDef:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            return node

        def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> ast.AsyncFunctionDef:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            return node

        def visit_ClassDef(self, node: ast.ClassDef) -> ast.ClassDef:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            return node

        def visit_If(self, node: ast.If) -> ast.If:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            node.orelse = self.generic_visit_stmt_list(node.orelse, is_module_level=False)
            return node

        def visit_For(self, node: ast.For) -> ast.For:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            node.orelse = self.generic_visit_stmt_list(node.orelse, is_module_level=False)
            return node

        def visit_AsyncFor(self, node: ast.AsyncFor) -> ast.AsyncFor:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            node.orelse = self.generic_visit_stmt_list(node.orelse, is_module_level=False)
            return node

        def visit_While(self, node: ast.While) -> ast.While:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            node.orelse = self.generic_visit_stmt_list(node.orelse, is_module_level=False)
            return node

        def visit_With(self, node: ast.With) -> ast.With:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            return node

        def visit_AsyncWith(self, node: ast.AsyncWith) -> ast.AsyncWith:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            return node

        def visit_Try(self, node: ast.Try) -> ast.Try:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            node.orelse = self.generic_visit_stmt_list(node.orelse, is_module_level=False)
            node.finalbody = self.generic_visit_stmt_list(node.finalbody, is_module_level=False)
            return node

        def visit_TryStar(self, node: ast.AST) -> ast.AST:
            if hasattr(node, "body"):
                node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            if hasattr(node, "orelse"):
                node.orelse = self.generic_visit_stmt_list(node.orelse, is_module_level=False)
            if hasattr(node, "finalbody"):
                node.finalbody = self.generic_visit_stmt_list(node.finalbody, is_module_level=False)
            return node

        def visit_match_case(self, node: ast.match_case) -> ast.match_case:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            return node

        def visit_ExceptHandler(self, node: ast.ExceptHandler) -> ast.ExceptHandler:
            node.body = self.generic_visit_stmt_list(node.body, is_module_level=False)
            return node

    cleaned_tree = DeadCodeCleaner().visit(tree)

    # Ensure compound statement bodies do not become empty
    for node in ast.walk(cleaned_tree):
        if hasattr(node, "body"):
            val = getattr(node, "body")
            if isinstance(val, list) and len(val) == 0 and not isinstance(node, ast.Module):
                setattr(node, "body", [ast.Pass()])

    ast.fix_missing_locations(cleaned_tree)
    result = ast.unparse(cleaned_tree)
    # Guarantee the transformed result compiles cleanly
    compile(result, "<string>", "exec")
    return result
