import threading
import time
from collections import OrderedDict
from typing import Any, Optional


class _CacheEntry:
    __slots__ = ("value", "expiry")

    def __init__(self, value: Any, expiry: float):
        self.value = value
        self.expiry = expiry


class TimeBoundedLRUCache:
    """Thread-safe LRU cache with time-to-live (TTL) expiration per item."""

    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("Capacity must be a positive integer.")
        if default_ttl_seconds <= 0:
            raise ValueError("Default TTL seconds must be positive.")

        self.capacity = capacity
        self.default_ttl_seconds = default_ttl_seconds
        self._cache: OrderedDict[str, _CacheEntry] = OrderedDict()
        self._lock = threading.RLock()

    def _cleanup_expired_unlocked(self, now: Optional[float] = None) -> int:
        if now is None:
            now = time.monotonic()
        expired_keys = [k for k, entry in self._cache.items() if now >= entry.expiry]
        for k in expired_keys:
            del self._cache[k]
        return len(expired_keys)

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self._lock:
            now = time.monotonic()
            ttl_seconds = self.default_ttl_seconds if ttl is None else ttl
            expiry = now + ttl_seconds

            if key in self._cache:
                self._cache[key] = _CacheEntry(value, expiry)
                self._cache.move_to_end(key)
                return

            self._cleanup_expired_unlocked(now)

            if len(self._cache) >= self.capacity:
                self._cache.popitem(last=False)

            self._cache[key] = _CacheEntry(value, expiry)

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            if key not in self._cache:
                return None

            entry = self._cache[key]
            now = time.monotonic()
            if now >= entry.expiry:
                del self._cache[key]
                return None

            self._cache.move_to_end(key)
            return entry.value

    def delete(self, key: str) -> bool:
        with self._lock:
            if key not in self._cache:
                return False

            entry = self._cache.pop(key)
            now = time.monotonic()
            return now < entry.expiry

    def cleanup_expired(self) -> int:
        with self._lock:
            return self._cleanup_expired_unlocked()

    def size(self) -> int:
        with self._lock:
            self._cleanup_expired_unlocked()
            return len(self._cache)
