class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected among tasks."""
    pass


class DependencyResolver:
    """Resolves task execution order into parallelizable stages."""

    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        """
        Resolves task dependencies into a list of execution stages.

        :param dependencies: Dictionary mapping task_name -> list of task_names it depends on.
        :return: List of stages, where each stage is a sorted list of task names.
        :raises CircularDependencyError: If a circular dependency exists.
        """
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        graph: dict[str, list[str]] = {task: [] for task in all_tasks}
        in_degree: dict[str, int] = {task: 0 for task in all_tasks}

        for task, deps in dependencies.items():
            unique_deps = set(deps)
            in_degree[task] = len(unique_deps)
            for dep in unique_deps:
                graph[dep].append(task)

        current_stage = [task for task, degree in in_degree.items() if degree == 0]

        stages: list[list[str]] = []
        processed_count = 0

        while current_stage:
            current_stage.sort()
            stages.append(current_stage)
            processed_count += len(current_stage)

            next_stage = []
            for task in current_stage:
                for dependent in graph[task]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_stage.append(dependent)

            current_stage = next_stage

        if processed_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected.")

        return stages
