import time
import threading
from collections import deque
from typing import Optional


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._lock = threading.Lock()
        self._requests: dict[str, deque[float]] = {}

    def _cleanup(self, dq: deque[float], now: float) -> None:
        cutoff = now - self.window_seconds
        while dq and dq[0] <= cutoff:
            dq.popleft()

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        now = time.time() if timestamp is None else float(timestamp)
        with self._lock:
            dq = self._requests.get(key)
            if dq is None:
                dq = deque()
                self._requests[key] = dq
            else:
                self._cleanup(dq, now)

            if len(dq) < self.max_requests:
                dq.append(now)
                return (True, 0.0)
            else:
                oldest = dq[0]
                retry_after = (oldest + self.window_seconds) - now
                return (False, max(0.0, retry_after))

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        now = time.time() if timestamp is None else float(timestamp)
        with self._lock:
            dq = self._requests.get(key)
            if dq is None:
                return self.max_requests

            self._cleanup(dq, now)
            if not dq:
                del self._requests[key]
                return self.max_requests

            return self.max_requests - len(dq)
