import asyncio
from typing import Optional, Callable, Any


class AsyncWorkerPool:
    """An asynchronous worker pool class using standard asyncio."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size <= 0:
            raise ValueError("max_queue_size must be greater than 0")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: list[asyncio.Task] = []
        self._is_started: bool = False
        self._is_shutting_down: bool = False
        self._counter: int = 0

    async def start(self) -> None:
        """Spawns worker tasks."""
        if self._is_started:
            return
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")
        self._is_started = True
        for i in range(self.concurrency):
            worker_task = asyncio.create_task(
                self._worker_loop(), name=f"AsyncWorkerPool-Worker-{i}"
            )
            self._workers.append(worker_task)

    async def submit(
        self, coro_func: Callable[..., Any], *args: Any, priority: int = 0, **kwargs: Any
    ) -> asyncio.Future:
        """
        Enqueues a coroutine function `coro_func(*args, **kwargs)` to be executed by pool workers.
        Higher priority integer values are executed before lower priority integer values.
        """
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        fut: asyncio.Future = loop.create_future()

        self._counter += 1
        # asyncio.PriorityQueue pops smaller values first.
        # Storing -priority ensures higher priority integers execute first.
        item = (-priority, self._counter, coro_func, args, kwargs, fut)

        await self._queue.put(item)
        return fut

    async def _worker_loop(self) -> None:
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            _, _, coro_func, args, kwargs, fut = item

            if fut.done():
                self._queue.task_done()
                continue

            task = asyncio.create_task(coro_func(*args, **kwargs))

            def _on_fut_cancelled(f: asyncio.Future) -> None:
                if f.cancelled() and not task.done():
                    task.cancel()

            fut.add_done_callback(_on_fut_cancelled)

            try:
                res = await task
                if not fut.done():
                    fut.set_result(res)
            except asyncio.CancelledError:
                if fut.cancelled():
                    # Future was cancelled by caller
                    pass
                else:
                    # Worker task itself was cancelled (e.g. during pool shutdown)
                    if not fut.done():
                        fut.cancel()
                    raise
            except BaseException as exc:
                if not fut.done():
                    fut.set_exception(exc)
            finally:
                fut.remove_done_callback(_on_fut_cancelled)
                self._queue.task_done()

    async def shutdown(
        self, drain: bool = True, timeout: Optional[float] = 5.0
    ) -> None:
        """
        Shuts down the worker pool.
        - If `drain=True`, waits for all queued tasks to finish before stopping workers.
        - If `drain=False`, cancels queued and executing tasks immediately.
        - Respects optional `timeout` seconds.
        """
        if self._is_shutting_down:
            return
        self._is_shutting_down = True

        async def _do_shutdown() -> None:
            if drain and self._is_started and self._workers:
                await self._queue.join()
            else:
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        _, _, _, _, _, fut = item
                        if not fut.done():
                            fut.cancel()
                        self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break

            for worker in self._workers:
                worker.cancel()
            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)

        if timeout is not None:
            try:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            except asyncio.TimeoutError:
                for worker in self._workers:
                    worker.cancel()
                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)
                raise
        else:
            await _do_shutdown()
