from typing import Any, Dict, List, Optional, Set, Tuple


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        """Initializes cluster state with the given node IDs and quorum threshold."""
        self.node_ids: list[str] = list(node_ids)
        self.total_nodes: int = len(self.node_ids)
        self.quorum_threshold: int = (self.total_nodes // 2) + 1

        # Maps node_id -> {key: (value, commit_sequence)}
        self._node_states: dict[str, dict[str, tuple[Any, int]]] = {
            node_id: {} for node_id in self.node_ids
        }

        # Maps node_id -> set of reachable node IDs in its partition
        self._partitions: dict[str, set[str]] = {
            node_id: set(self.node_ids) for node_id in self.node_ids
        }

        # Monotonically increasing sequence number for write versioning
        self._seq: int = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """Divides the cluster into isolated network partitions group_a and group_b."""
        group_a_set = set(group_a)
        group_b_set = set(group_b)

        for node_id in self.node_ids:
            if node_id in group_a_set:
                self._partitions[node_id] = set(group_a_set)
            elif node_id in group_b_set:
                self._partitions[node_id] = set(group_b_set)
            else:
                self._partitions[node_id] = {node_id}

    def heal_partition(self) -> None:
        """Restores full connectivity and synchronizes committed state across all nodes."""
        all_nodes = set(self.node_ids)
        for node_id in self.node_ids:
            self._partitions[node_id] = set(all_nodes)

        # Determine the latest committed version for each key across all nodes
        latest_state: dict[str, tuple[Any, int]] = {}
        for node_id in self.node_ids:
            for key, entry in self._node_states[node_id].items():
                if key not in latest_state or entry[1] > latest_state[key][1]:
                    latest_state[key] = entry

        # Synchronize all nodes with the latest state
        for node_id in self.node_ids:
            self._node_states[node_id] = dict(latest_state)

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """Proposes a write from `from_node`.

        Commits if `from_node` belongs to a majority partition, updating state
        for all nodes in that partition and returning True. Rejects and returns
        False if in a minority partition.
        """
        if from_node not in self._partitions:
            return False

        active_partition = self._partitions[from_node]
        if len(active_partition) >= self.quorum_threshold:
            self._seq += 1
            for node_id in active_partition:
                if node_id in self._node_states:
                    self._node_states[node_id][key] = (value, self._seq)
            return True

        return False

    def read_value(self, from_node: str, key: str) -> Any:
        """Returns the committed value for `key` on `from_node` (or None if not set)."""
        if from_node in self._node_states and key in self._node_states[from_node]:
            return self._node_states[from_node][key][0]
        return None
