import threading


class ResilientConnectionPool:
    """A thread-safe database connection pool wrapper that supports health checking and healing."""

    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if max_connections <= 0:
            raise ValueError("max_connections must be greater than 0")
        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()
        self._next_id = 1
        self._connections = []
        self._available = []

        for _ in range(self.max_connections):
            conn = {"id": self._next_id, "alive": True}
            self._next_id += 1
            self._connections.append(conn)
            self._available.append(conn)

    def acquire(self) -> dict:
        """Returns an active connection object {"id": int, "alive": bool}.

        Raises RuntimeError if no active available connections remain.
        """
        with self._lock:
            for i, conn in enumerate(self._available):
                if conn.get("alive", False):
                    return self._available.pop(i)
            raise RuntimeError("Pool exhausted")

    def release(self, conn: dict) -> None:
        """Returns a connection back to the pool."""
        with self._lock:
            if not isinstance(conn, dict):
                return
            if conn in self._connections and conn not in self._available:
                self._available.append(conn)

    def health_check_and_heal(self) -> int:
        """Iterates over pool connections, checks if conn['alive'] is False,

        recreates them with new alive connections, and returns the number of
        healed connections.
        """
        with self._lock:
            healed = 0
            for i in range(len(self._connections)):
                conn = self._connections[i]
                if not conn.get("alive", False):
                    new_conn = {"id": self._next_id, "alive": True}
                    self._next_id += 1
                    self._connections[i] = new_conn

                    if conn in self._available:
                        idx = self._available.index(conn)
                        self._available[idx] = new_conn
                    else:
                        self._available.append(new_conn)

                    healed += 1
            return healed

    def close_all(self) -> None:
        """Closes and empties the pool."""
        with self._lock:
            for conn in self._connections:
                conn["alive"] = False
            self._connections.clear()
            self._available.clear()
