import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    """Refactors Python source code to remove unused imports and unreferenced top-level

    private functions while preserving docstrings, class definitions, and global
    variables.
    """
    tree = ast.parse(source_code)

    top_level_private_func_nodes = set()
    private_func_dict = {}
    root_nodes = []

    # Separate module body into candidate private functions vs root (entry point) nodes
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if stmt.name.startswith('_') and not (
                stmt.name.startswith('__') and stmt.name.endswith('__')
            ):
                top_level_private_func_nodes.add(stmt)
                private_func_dict.setdefault(stmt.name, []).append(stmt)
            else:
                root_nodes.append(stmt)
        elif isinstance(stmt, (ast.Import, ast.ImportFrom)):
            pass  # Imports are candidates for pruning
        else:
            root_nodes.append(stmt)

    def get_referenced_names(node: ast.AST) -> set[str]:
        """Collects all referenced identifiers within an AST node subtree."""
        names = set()
        for subnode in ast.walk(node):
            if isinstance(subnode, ast.Name):
                names.add(subnode.id)
            elif isinstance(subnode, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
                targets = (
                    subnode.targets
                    if isinstance(subnode, ast.Assign)
                    else [subnode.target]
                )
                for target in targets:
                    if isinstance(target, ast.Name) and target.id == '__all__':
                        val = subnode.value
                        if isinstance(val, (ast.List, ast.Tuple, ast.Set)):
                            for elt in val.elts:
                                if isinstance(elt, ast.Constant) and isinstance(
                                    elt.value, str
                                ):
                                    names.add(elt.value)
                                elif isinstance(elt, ast.Str):
                                    names.add(elt.s)
        return names

    # Perform graph reachability analysis to discover all reachable functions & names
    reachable_names = set()
    worklist = []

    for stmt in root_nodes:
        for ref in get_referenced_names(stmt):
            if ref not in reachable_names:
                reachable_names.add(ref)
                worklist.append(ref)

    while worklist:
        curr_name = worklist.pop()
        if curr_name in private_func_dict:
            for fn_node in private_func_dict[curr_name]:
                for ref in get_referenced_names(fn_node):
                    if ref not in reachable_names:
                        reachable_names.add(ref)
                        worklist.append(ref)

    # AST Transformer to prune unreferenced private functions and unused import names
    class PruneTransformer(ast.NodeTransformer):

        def visit_FunctionDef(self, node: ast.FunctionDef):
            if (
                node in top_level_private_func_nodes
                and node.name not in reachable_names
            ):
                return None
            return self.generic_visit(node)

        def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef):
            if (
                node in top_level_private_func_nodes
                and node.name not in reachable_names
            ):
                return None
            return self.generic_visit(node)

        def visit_Import(self, node: ast.Import):
            new_aliases = []
            for alias in node.names:
                bound_name = (
                    alias.asname
                    if alias.asname
                    else alias.name.split('.')[0]
                )
                if bound_name in reachable_names:
                    new_aliases.append(alias)
            if not new_aliases:
                return None
            node.names = new_aliases
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom):
            if node.module == '__future__':
                return node
            new_aliases = []
            for alias in node.names:
                if alias.name == '*':
                    new_aliases.append(alias)
                else:
                    bound_name = alias.asname if alias.asname else alias.name
                    if bound_name in reachable_names:
                        new_aliases.append(alias)
            if not new_aliases:
                return None
            node.names = new_aliases
            return node

    transformer = PruneTransformer()
    transformed_tree = transformer.visit(tree)
    ast.fix_missing_locations(transformed_tree)

    result_code = ast.unparse(transformed_tree)
    compile(result_code, '<string>', 'exec')
    return result_code
