import time
import threading
from typing import Optional

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._lock = threading.Lock()
        self._history: dict[str, list[float]] = {}

    def _clean_and_get_history(self, key: str, now: float) -> list[float]:
        boundary = now - self.window_seconds
        history = [t for t in self._history.get(key, []) if t > boundary]
        if not history:
            self._history.pop(key, None)
        else:
            history.sort()
            self._history[key] = history
        return history

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        now = timestamp if timestamp is not None else time.time()
        with self._lock:
            history = self._clean_and_get_history(key, now)
            if len(history) < self.max_requests:
                history.append(now)
                self._history[key] = history
                return True, 0.0
            else:
                if not history:
                    return False, float('inf')
                oldest = history[0]
                retry_after = oldest + self.window_seconds - now
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        now = timestamp if timestamp is not None else time.time()
        with self._lock:
            history = self._clean_and_get_history(key, now)
            return max(0, self.max_requests - len(history))
