import asyncio
from typing import Optional, Set, List

class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        self._concurrency = concurrency
        self._max_queue_size = max_queue_size
        self._queue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: List[asyncio.Task] = []
        self._running = False
        self._shutting_down = False
        self._counter = 0
        self._active_tasks: Set[asyncio.Task] = set()
        self._pending_puts: Set[asyncio.Task] = set()

    async def start(self) -> None:
        """Spawns worker tasks to process the queued coroutines."""
        if self._running or self._shutting_down:
            return
        self._running = True
        self._workers = [
            asyncio.create_task(self._worker())
            for _ in range(self._concurrency)
        ]

    async def submit(self, coro_func, *args, priority: int = 0, **kwargs) -> asyncio.Future:
        """
        Enqueues a coroutine function `coro_func(*args, **kwargs)` to be executed by the pool workers.
        Higher priority integer executes before lower priority integers.
        """
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future = loop.create_future()

        self._counter += 1
        counter = self._counter

        # PriorityQueue retrieves lowest values first.
        # Store negative priority to process higher priority values first.
        # Counter is used to maintain FIFO order for equal priorities and avoid uncomparable type errors.
        item = (-priority, counter, (coro_func, args, kwargs, future))

        current_task = asyncio.current_task()
        if current_task is not None:
            self._pending_puts.add(current_task)

        try:
            await self._queue.put(item)
        except asyncio.CancelledError:
            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")
            raise
        finally:
            if current_task is not None:
                self._pending_puts.discard(current_task)

        return future

    async def _worker(self) -> None:
        while True:
            try:
                priority, counter, (coro_func, args, kwargs, future) = await self._queue.get()
            except asyncio.CancelledError:
                # Worker task was cancelled during shutdown while waiting for queue
                break

            if future.done():
                self._queue.task_done()
                continue

            task = asyncio.create_task(coro_func(*args, **kwargs))
            self._active_tasks.add(task)

            # Link future cancellation to task cancellation
            def link_cancellation(fut, t=task):
                if fut.cancelled() and not t.done():
                    t.cancel()

            future.add_done_callback(link_cancellation)

            try:
                # Wait for the task to finish execution.
                # Using asyncio.wait prevents a user-initiated future cancellation
                # from propagating CancelledError to this worker task.
                await asyncio.wait({task})

                if task.cancelled():
                    if not future.done():
                        future.cancel()
                elif task.exception() is not None:
                    exc = task.exception()
                    if not future.done() and exc is not None:
                        future.set_exception(exc)
                else:
                    result = task.result()
                    if not future.done():
                        future.set_result(result)
            except asyncio.CancelledError:
                # Worker task itself was cancelled during shutdown
                if not task.done():
                    task.cancel()
                if not future.done():
                    future.cancel()
                raise
            finally:
                self._active_tasks.discard(task)
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """
        Shuts down the worker pool.
        If drain=True, waits for all enqueued tasks to finish.
        If drain=False, cancels all queued and currently executing tasks immediately.
        """
        if not self._running or self._shutting_down:
            return
        self._shutting_down = True

        # Cancel any pending submit/put calls
        for put_task in list(self._pending_puts):
            if not put_task.done():
                put_task.cancel()

        async def _do_shutdown():
            if drain:
                # Wait for queue to empty and all tasks to finish processing
                await self._queue.join()
                # Cancel workers
                for w in self._workers:
                    w.cancel()
            else:
                # Cancel queued tasks
                while not self._queue.empty():
                    try:
                        _, _, (_, _, _, future) = self._queue.get_nowait()
                        if not future.done():
                            future.cancel()
                        self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break

                # Cancel active tasks
                for task in list(self._active_tasks):
                    if not task.done():
                        task.cancel()

                # Cancel workers
                for w in self._workers:
                    w.cancel()

            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)

        try:
            if timeout is not None:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            else:
                await _do_shutdown()
        except asyncio.TimeoutError:
            # Force cancel everything if timeout occurs
            for task in list(self._active_tasks):
                if not task.done():
                    task.cancel()
            for w in self._workers:
                if not w.done():
                    w.cancel()
            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)
        finally:
            self._running = False
