class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        # Keep unique node IDs preserving order
        self.node_ids = list(dict.fromkeys(node_ids))
        self.quorum = len(self.node_ids) // 2 + 1

        # Each node maps key -> (value, version)
        self.states = {node_id: {} for node_id in self.node_ids}

        # Initially, all nodes are in a single partition
        self.partitions = [set(self.node_ids)]

    def _synchronize_partition(self, partition_nodes: set[str]) -> None:
        """Synchronizes the state across all nodes in the given partition,
        adopting the value with the highest version for each key.
        """
        # Collect all keys present in this partition
        all_keys = set()
        for node in partition_nodes:
            all_keys.update(self.states[node].keys())

        # For each key, find the highest version and propagate it
        for key in all_keys:
            max_version = -1
            best_value = None
            for node in partition_nodes:
                if key in self.states[node]:
                    val, ver = self.states[node][key]
                    if ver > max_version:
                        max_version = ver
                        best_value = val
            if max_version != -1:
                for node in partition_nodes:
                    self.states[node][key] = (best_value, max_version)

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        # Filter to make sure we only include valid nodes in the cluster
        group_a_set = set(group_a) & set(self.node_ids)
        group_b_set = (set(group_b) & set(self.node_ids)) - group_a_set
        other_nodes = set(self.node_ids) - group_a_set - group_b_set

        self.partitions = []
        if group_a_set:
            self.partitions.append(group_a_set)
        if group_b_set:
            self.partitions.append(group_b_set)
        for node in other_nodes:
            self.partitions.append({node})

        # Synchronize states within each new partition
        for part in self.partitions:
            self._synchronize_partition(part)

    def heal_partition(self) -> None:
        # Restore full connectivity (all nodes in one partition)
        self.partitions = [set(self.node_ids)]
        # Synchronize states across all nodes
        self._synchronize_partition(self.partitions[0])

    def propose_write(self, from_node: str, key: str, value: any) -> bool:
        # Find the partition containing the proposer node
        target_partition = None
        for part in self.partitions:
            if from_node in part:
                target_partition = part
                break

        if not target_partition or len(target_partition) < self.quorum:
            return False

        # Find the max version of this key within the partition
        max_version = 0
        for node in target_partition:
            if key in self.states[node]:
                _, ver = self.states[node][key]
                if ver > max_version:
                    max_version = ver

        # Update all nodes in the partition with the new value and incremented version
        new_version = max_version + 1
        for node in target_partition:
            self.states[node][key] = (value, new_version)

        return True

    def read_value(self, from_node: str, key: str) -> any:
        if from_node not in self.node_ids:
            return None
        if key not in self.states[from_node]:
            return None
        return self.states[from_node][key][0]
