import base64
import json
import hmac
import hashlib
import time

def verify_jwt(token: str, secret_key: str, allowed_algs: list[str] = ["HS256"]) -> dict:
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    # Helper for proper Base64 URL decoding with dynamic padding
    def base64url_decode(s: str) -> bytes:
        rem = len(s) % 4
        if rem:
            s += "=" * (4 - rem)
        return base64.urlsafe_b64decode(s)

    try:
        header_raw = base64url_decode(parts[0])
        header = json.loads(header_raw)
    except Exception as e:
        raise ValueError("Invalid header encoding or format") from e

    try:
        payload_raw = base64url_decode(parts[1])
        payload = json.loads(payload_raw)
    except Exception as e:
        raise ValueError("Invalid payload encoding or format") from e

    # Fix BUG 1: Validate algorithm strictly against allowed_algs
    alg = header.get("alg")
    if alg not in allowed_algs:
        raise ValueError("Algorithm not allowed")

    # Fix BUG 2: Validate expiration (required exp check, exact timestamp validation)
    if "exp" not in payload:
        raise ValueError("Missing expiration claim")

    now = time.time()
    try:
        exp_val = float(payload["exp"])
    except (ValueError, TypeError) as e:
        raise ValueError("Invalid exp claim format") from e

    if exp_val <= now:
        raise ValueError("Token expired")

    # If alg is "none", ensure signature part is empty and return payload
    if alg == "none":
        if parts[2] != "":
            raise ValueError("Signature must be empty for algorithm 'none'")
        return payload

    # Verify HMAC signature
    try:
        signature = base64url_decode(parts[2])
    except Exception as e:
        raise ValueError("Invalid signature encoding") from e

    signing_input = f"{parts[0]}.{parts[1]}".encode("utf-8")

    # Determine hashing algorithm based on the header alg
    if alg == "HS256":
        hash_alg = hashlib.sha256
    elif alg == "HS384":
        hash_alg = hashlib.sha384
    elif alg == "HS512":
        hash_alg = hashlib.sha512
    else:
        raise ValueError("Unsupported algorithm")

    expected_sig = hmac.new(secret_key.encode("utf-8"), signing_input, hash_alg).digest()

    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")

    return payload
