import threading

class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()
        self._next_id = 1
        self._connections = {}  # Map of id -> connection dict
        self._available = []    # List of available connection dicts

        for _ in range(max_connections):
            conn = {"id": self._next_id, "alive": True}
            self._connections[conn["id"]] = conn
            self._available.append(conn)
            self._next_id += 1

    def acquire(self) -> dict:
        with self._lock:
            if not self._available:
                raise RuntimeError("Pool exhausted")
            return self._available.pop(0)

    def release(self, conn: dict) -> None:
        with self._lock:
            conn_id = conn.get("id")
            if conn_id not in self._connections:
                # The connection does not belong to this pool or was already healed/removed
                return
            if conn not in self._available:
                self._available.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            healed_count = 0
            for conn_id, conn in list(self._connections.items()):
                if not conn.get("alive", False):
                    new_conn = {"id": self._next_id, "alive": True}
                    self._next_id += 1

                    # Replace old connection in registration map
                    self._connections[new_conn["id"]] = new_conn
                    del self._connections[conn_id]

                    # Update available list
                    if conn in self._available:
                        idx = self._available.index(conn)
                        self._available[idx] = new_conn
                    else:
                        self._available.append(new_conn)

                    healed_count += 1
            return healed_count

    def close_all(self) -> None:
        with self._lock:
            for conn in self._connections.values():
                conn["alive"] = False
            self._connections.clear()
            self._available.clear()
