import ast

def prune_dead_code_and_imports(source_code: str) -> str:
    try:
        tree = ast.parse(source_code)
    except SyntaxError as e:
        raise e

    # 1. Collect names referenced in any AST node
    def collect_names(node):
        names = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                names.add(child.id)
            elif isinstance(child, ast.Global):
                names.update(child.names)
            elif isinstance(child, ast.Nonlocal):
                names.update(child.names)
        return names

    # 2. Identify top-level private functions (P)
    P = {}  # name -> node
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            name = node.name
            # Private function starts with '_' and is not a dunder (starts/ends with '__')
            if name.startswith('_') and not (name.startswith('__') and name.endswith('__')):
                P[name] = node

    # 3. Identify imported bound names (I) anywhere in the AST
    I = {}  # bound_name -> (node, alias)
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                bound_name = alias.asname if alias.asname else alias.name.split('.')[0]
                I[bound_name] = (node, alias)
        elif isinstance(node, ast.ImportFrom):
            if node.names and node.names[0].name == '*':
                # Skip wildcard imports so they are kept intact
                continue
            for alias in node.names:
                bound_name = alias.asname if alias.asname else alias.name
                I[bound_name] = (node, alias)

    # 4. Collect references within functions and at the module level
    Refs = {}
    RootRefs = set()

    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name in P:
            Refs[node.name] = collect_names(node)
        else:
            RootRefs.update(collect_names(node))

    # 5. BFS to find reachable (live) private functions
    Live = RootRefs.intersection(P.keys())
    Q = list(Live)
    while Q:
        curr = Q.pop(0)
        for ref in Refs.get(curr, []):
            if ref in P and ref not in Live:
                Live.add(ref)
                Q.append(ref)

    # 6. Determine live imports
    LiveImports = set()
    for imp in I:
        if imp in RootRefs:
            LiveImports.add(imp)
        else:
            for f in Live:
                if imp in Refs.get(f, []):
                    LiveImports.add(imp)
                    break

    # 7. Apply pruning transformer to the AST
    nodes_to_remove = {node for name, node in P.items() if name not in Live}

    class PruningTransformer(ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            if node in nodes_to_remove:
                return None
            return self.generic_visit(node)

        def visit_AsyncFunctionDef(self, node):
            if node in nodes_to_remove:
                return None
            return self.generic_visit(node)

        def visit_Import(self, node):
            new_names = []
            for alias in node.names:
                bound_name = alias.asname if alias.asname else alias.name.split('.')[0]
                if bound_name in LiveImports:
                    new_names.append(alias)
            if not new_names:
                return None
            node.names = new_names
            return node

        def visit_ImportFrom(self, node):
            if node.names and node.names[0].name == '*':
                return node
            new_names = []
            for alias in node.names:
                bound_name = alias.asname if alias.asname else alias.name
                if bound_name in LiveImports:
                    new_names.append(alias)
            if not new_names:
                return None
            node.names = new_names
            return node

    transformer = PruningTransformer()
    new_tree = transformer.visit(tree)
    ast.fix_missing_locations(new_tree)

    return ast.unparse(new_tree)
