import threading
import time
from collections import OrderedDict
from typing import Optional, Any

class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.default_ttl = default_ttl_seconds
        self.cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self.lock = threading.RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self.lock:
            actual_ttl = ttl if ttl is not None else self.default_ttl
            expiry_time = time.time() + actual_ttl

            if key in self.cache:
                self.cache.move_to_end(key)
                self.cache[key] = (value, expiry_time)
                return

            if len(self.cache) >= self.capacity:
                evict_key = None
                now = time.time()
                # Find the oldest expired item (first expired item in LRU order)
                for k, (_, exp) in self.cache.items():
                    if exp <= now:
                        evict_key = k
                        break

                # If no expired items, evict the least recently used non-expired item
                if evict_key is None:
                    evict_key = next(iter(self.cache))

                del self.cache[evict_key]

            self.cache[key] = (value, expiry_time)

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            if key in self.cache:
                value, expiry_time = self.cache[key]
                if expiry_time > time.time():
                    self.cache.move_to_end(key)
                    return value
                else:
                    del self.cache[key]
            return None

    def delete(self, key: str) -> bool:
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self.lock:
            now = time.time()
            expired_keys = [k for k, (_, exp) in self.cache.items() if exp <= now]
            for k in expired_keys:
                del self.cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self.lock:
            now = time.time()
            return sum(1 for _, exp in self.cache.values() if exp > now)
