class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        if not dependencies:
            return []

        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        deps_count = {task: 0 for task in all_tasks}
        reverse_graph = {task: set() for task in all_tasks}

        for task, deps in dependencies.items():
            deps_set = set(deps)
            deps_count[task] += len(deps_set)
            for dep in deps_set:
                reverse_graph[dep].add(task)

        stages = []
        processed_count = 0

        while True:
            current_stage = [task for task, count in deps_count.items() if count == 0]

            if not current_stage:
                break

            current_stage.sort()
            stages.append(current_stage)
            processed_count += len(current_stage)

            for task in current_stage:
                del deps_count[task]
                for dependent in reverse_graph[task]:
                    deps_count[dependent] -= 1

        if processed_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected in tasks.")

        return stages
