import time
import threading
from collections import defaultdict, deque
from typing import Optional


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.requests = defaultdict(deque)
        self.lock = threading.Lock()

    def _cleanup(self, key: str, current_time: float) -> None:
        """Removes timestamps outside the current sliding window for the given key."""
        if key not in self.requests:
            return

        window_start = current_time - self.window_seconds
        q = self.requests[key]

        while q and q[0] <= window_start:
            q.popleft()

        # Clean up the key entirely if there are no requests left
        if not q:
            del self.requests[key]

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        if self.max_requests <= 0:
            return False, float('inf')

        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup(key, timestamp)
            q = self.requests[key]

            if len(q) < self.max_requests:
                q.append(timestamp)
                return True, 0.0
            else:
                retry_after = (q[0] + self.window_seconds) - timestamp
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if self.max_requests <= 0:
            return 0

        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup(key, timestamp)
            q = self.requests.get(key)

            if not q:
                return self.max_requests

            return max(0, self.max_requests - len(q))
