import asyncio
import dataclasses
import itertools
from typing import Any, Callable, Coroutine, Dict, List, Optional, Tuple

@dataclasses.dataclass(order=True)
class _PrioritizedItem:
    priority: int
    sequence: int
    future: asyncio.Future = dataclasses.field(compare=False)
    func: Callable[..., Coroutine[Any, Any, Any]] = dataclasses.field(compare=False)
    args: Tuple[Any, ...] = dataclasses.field(compare=False)
    kwargs: Dict[str, Any] = dataclasses.field(compare=False)

class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        self.concurrency = concurrency
        self.max_queue_size = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: List[asyncio.Task] = []
        self._shutting_down = False
        self._seq_counter = itertools.count()

    async def start(self) -> None:
        """Spawns worker tasks to process the queue."""
        if self._workers:
            return

        self._shutting_down = False
        loop = asyncio.get_running_loop()

        for _ in range(self.concurrency):
            task = loop.create_task(self._worker())
            self._workers.append(task)

    async def submit(self, coro_func: Callable[..., Coroutine[Any, Any, Any]], *args: Any, priority: int = 0, **kwargs: Any) -> asyncio.Future:
        """
        Enqueues a coroutine function to be executed by the pool.
        Higher priority executes before lower priority integers.
        """
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future = loop.create_future()

        # We store negative priority because PriorityQueue yields the lowest value first
        item = _PrioritizedItem(
            priority=-priority,
            sequence=next(self._seq_counter),
            future=future,
            func=coro_func,
            args=args,
            kwargs=kwargs
        )

        await self._queue.put(item)
        return future

    async def _worker(self) -> None:
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            if item.future.cancelled():
                self._queue.task_done()
                continue

            try:
                result = await item.func(*item.args, **item.kwargs)
                if not item.future.done():
                    item.future.set_result(result)
            except asyncio.CancelledError:
                if not item.future.done():
                    item.future.cancel()
                self._queue.task_done()
                raise  # Re-raise to cleanly terminate this worker task
            except Exception as e:
                if not item.future.done():
                    item.future.set_exception(e)

            self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """
        Shuts down the worker pool.
        If drain=True, waits for currently queued tasks to complete.
        If drain=False, forcefully cancels all queued and executing tasks immediately.
        Respects the optional timeout (in seconds).
        """
        self._shutting_down = True

        async def _shutdown_process() -> None:
            if drain:
                await self._queue.join()

            for worker in self._workers:
                worker.cancel()

            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)

            while not self._queue.empty():
                try:
                    item = self._queue.get_nowait()
                    if not item.future.done():
                        item.future.cancel()
                    self._queue.task_done()
                except asyncio.QueueEmpty:
                    break

        try:
            if timeout is not None:
                await asyncio.wait_for(_shutdown_process(), timeout=timeout)
            else:
                await _shutdown_process()
        except asyncio.TimeoutError:
            # Force cancel all workers and empty the queue if timeout occurs
            for worker in self._workers:
                worker.cancel()

            while not self._queue.empty():
                try:
                    item = self._queue.get_nowait()
                    if not item.future.done():
                        item.future.cancel()
                    self._queue.task_done()
                except asyncio.QueueEmpty:
                    break
        finally:
            self._workers.clear()
