from typing import Any

class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        self.nodes = set(node_ids)
        self.threshold = (len(node_ids) // 2) + 1

        # Initially, all nodes are in a single partition
        self.partitions = [set(node_ids)]

        # State mapping: node_id -> {key: (version, value)}
        self.state = {node: {} for node in node_ids}

        # Global counter to keep track of the latest writes
