        for node in self.nodes:
            self.state[node] = dict(latest_state)

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        active_partition = None
        for p in self.partitions:
            if from_node in p:
                active_partition = p
                break

        # Reject write if the node is in a minority partition (or not in any partition)
        if active_partition is None or len(active_partition) < self.threshold:
            return False

        # Accept write: Update the value in all nodes within the majority partition
        self.global_version += 1
        for node in active_partition:
            if node in self.state:
                self.state[node][key] = (self.global_version, value)

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        node_data = self.state.get(from_node)
        if node_data and key in node_data:
            return node_data[key][1]
        return None
