import threading

class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self.pool = {i: {"id": i, "alive": True} for i in range(max_connections)}
        self.available_ids = list(range(max_connections))
        self.lock = threading.Lock()

    def acquire(self) -> dict:
        with self.lock:
            if not self.available_ids:
                raise RuntimeError("Pool exhausted")
            conn_id = self.available_ids.pop(0)
            return self.pool[conn_id]

    def release(self, conn: dict) -> None:
        with self.lock:
            conn_id = conn.get("id")
            # Ensure the connection is part of the active pool and not already released
            if conn_id in self.pool and conn_id not in self.available_ids:
                self.available_ids.append(conn_id)

    def health_check_and_heal(self) -> int:
        healed_count = 0
        with self.lock:
            for conn_id, conn in self.pool.items():
                if conn.get("alive") is False:
                    # Recreate with a new alive connection
                    self.pool[conn_id] = {"id": conn_id, "alive": True}
                    healed_count += 1
        return healed_count

    def close_all(self) -> None:
        with self.lock:
            self.pool.clear()
            self.available_ids.clear()
