from collections import defaultdict
from typing import Dict, List


class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(self, dependencies: Dict[str, List[str]]) -> List[List[str]]:
        tasks = set(dependencies)
        for required_tasks in dependencies.values():
            tasks.update(required_tasks)

        in_degree = {task: 0 for task in tasks}
        dependents = defaultdict(list)

        for task, required_tasks in dependencies.items():
            for required_task in required_tasks:
                in_degree[task] += 1
                dependents[required_task].append(task)

        stages = []
        ready = sorted(task for task, degree in in_degree.items() if degree == 0)
        processed = 0

        while ready:
            stages.append(ready)
            processed += len(ready)

            next_ready = []
            for task in ready:
                for dependent in dependents[task]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_ready.append(dependent)

            ready = sorted(next_ready)

        if processed != len(tasks):
            raise CircularDependencyError("Circular dependency detected")

        return stages
