import asyncio
import itertools
from typing import Any, Awaitable, Callable, Optional


class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        if concurrency < 1:
            raise ValueError("concurrency must be at least 1")
        if max_queue_size < 1:
            raise ValueError("max_queue_size must be at least 1")

        self._concurrency = concurrency
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(max_queue_size)
        self._counter = itertools.count()
        self._workers: list[asyncio.Task] = []
        self._started = False
        self._shutting_down = False
        self._state_lock = asyncio.Lock()

    async def start(self) -> None:
        async with self._state_lock:
            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")

            if self._started:
                return

            self._started = True
            self._workers = [
                asyncio.create_task(self._worker(), name=f"async-worker-pool-{i}")
                for i in range(self._concurrency)
            ]

    async def submit(
        self,
        coro_func: Callable[..., Awaitable[Any]],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        async with self._state_lock:
            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")

            if not self._started:
                await self.start()

            loop = asyncio.get_running_loop()
            future = loop.create_future()
            sequence = next(self._counter)

            await self._queue.put(
                (-priority, sequence, coro_func, args, kwargs, future)
            )
            return future

    async def shutdown(
        self,
        drain: bool = True,
        timeout: Optional[float] = 5.0,
    ) -> None:
        async with self._state_lock:
            if self._shutting_down:
                return

            self._shutting_down = True

            async def stop_workers() -> None:
                if drain:
                    await self._queue.join()

                    for _ in self._workers:
                        await self._queue.put((float("inf"), next(self._counter), None, (), {}, None))
                else:
                    self._cancel_queued_futures()
                    for worker in self._workers:
                        worker.cancel()

                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)

            try:
                if timeout is None:
                    await stop_workers()
                else:
                    await asyncio.wait_for(stop_workers(), timeout=timeout)
            except asyncio.TimeoutError:
                self._cancel_queued_futures()
                for worker in self._workers:
                    worker.cancel()
                await asyncio.gather(*self._workers, return_exceptions=True)
                raise
            finally:
                self._workers.clear()

    async def _worker(self) -> None:
        while True:
            _, _, coro_func, args, kwargs, future = await self._queue.get()

            try:
                if coro_func is None:
                    return

                if future.cancelled():
                    continue

                try:
                    result = await coro_func(*args, **kwargs)
                except asyncio.CancelledError:
                    if not future.done():
                        future.cancel()
                    raise
                except Exception as exc:
                    if not future.done():
                        future.set_exception(exc)
                else:
                    if not future.done():
                        future.set_result(result)
            finally:
                self._queue.task_done()

    def _cancel_queued_futures(self) -> None:
        while True:
            try:
                _, _, _, _, _, future = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                break
            else:
                if future is not None and not future.done():
                    future.cancel()
                self._queue.task_done()
