from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        if not node_ids or len(node_ids) != len(set(node_ids)):
            raise ValueError("node_ids must be non-empty and unique")

        self.node_ids = set(node_ids)
        self.node_count = len(node_ids)
        self.quorum_threshold = self.node_count // 2 + 1
        self._states: dict[str, dict[str, Any]] = {node: {} for node in node_ids}
        self._partitions: list[set[str]] | None = None
        self._committed_state: dict[str, Any] = {}

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        a, b = set(group_a), set(group_b)

        if not a or not b:
            raise ValueError("Both partition groups must be non-empty")
        if a & b:
            raise ValueError("Partition groups must not overlap")
        if a | b != self.node_ids:
            raise ValueError("Partition groups must contain every cluster node exactly once")

        self._partitions = [a, b]

    def heal_partition(self) -> None:
        for node in self.node_ids:
            self._states[node] = self._committed_state.copy()
        self._partitions = None

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        if from_node not in self.node_ids:
            raise ValueError(f"Unknown node: {from_node}")

        active_group = self._active_group(from_node)

        if len(active_group) < self.quorum_threshold:
            return False

        self._committed_state[key] = value
        for node in active_group:
            self._states[node][key] = value

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self.node_ids:
            raise ValueError(f"Unknown node: {from_node}")

        return self._states[from_node].get(key)

    def _active_group(self, node_id: str) -> set[str]:
        if self._partitions is None:
            return self.node_ids

        for group in self._partitions:
            if node_id in group:
                return group

        raise ValueError(f"Node is not assigned to a partition: {node_id}")
