def verify_jwt(
    token: str,
    secret_key: str,
    allowed_algs: list[str] | None = None,
) -> dict:
    allowed_algs = allowed_algs or ["HS256"]

    def decode_base64url(segment: str) -> bytes:
        try:
            padding = "=" * (-len(segment) % 4)
            return base64.b64decode(
                (segment + padding).encode("ascii"),
                altchars=b"-_",
                validate=True,
            )
        except (ValueError, UnicodeEncodeError, base64.binascii.Error) as exc:
            raise ValueError("Invalid Base64 URL encoding") from exc

    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    try:
        header = json.loads(decode_base64url(parts[0]))
        payload = json.loads(decode_base64url(parts[1]))
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JWT JSON") from exc

    if not isinstance(header, dict) or not isinstance(payload, dict):
        raise ValueError("Invalid JWT structure")

    alg = header.get("alg")
    # This verifier implements only HS256; it must also be explicitly allowed.
    if alg != "HS256" or alg not in allowed_algs:
        raise ValueError("Unapproved JWT algorithm")

    signing_input = f"{parts[0]}.{parts[1]}".encode("utf-8")
    expected_sig = hmac.new(
        secret_key.encode("utf-8"),
        signing_input,
        hashlib.sha256,
    ).digest()

    signature = decode_base64url(parts[2])
    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")

    if "exp" in payload:
        exp = payload["exp"]
        if isinstance(exp, bool) or not isinstance(exp, (int, float)):
            raise ValueError("Invalid exp claim")
        if exp <= time.time():
            raise ValueError("Token expired")

    return payload
