def is_safe_sql_query(query: str) -> tuple[bool, str]:
    from decimal import Decimal, InvalidOperation
    import re

    if not isinstance(query, str):
        return False, "INVALID_QUERY_TYPE"
    if not query.strip():
        return False, "EMPTY_QUERY"
    if "\x00" in query:
        return False, "INVALID_CHARACTER"

    literals: list[str] = []
    normalized_parts: list[str] = []
    i = 0
    length = len(query)

    while i < length:
        char = query[i]

        # SQL comments are commonly used to evade validation or terminate clauses.
        if query.startswith("/*!", i):
            return False, "OBFUSCATED_COMMENT"
        if query.startswith("/*", i):
            return False, "INLINE_COMMENT"
        if query.startswith("--", i) or char == "#":
            return False, "INLINE_COMMENT"

        # PostgreSQL dollar-quoted strings.
        dollar_match = re.match(r"\$[A-Za-z_][A-Za-z0-9_]*\$|\$\$", query[i:])
        if dollar_match:
            delimiter = dollar_match.group(0)
            end = query.find(delimiter, i + len(delimiter))
            if end == -1:
                return False, "MALFORMED_QUERY"
            literals.append(query[i + len(delimiter):end])
            normalized_parts.append(f" __str_{len(literals) - 1}__ ")
            i = end + len(delimiter)
            continue

        # Single-quoted string literals.
        if char == "'":
            start = i + 1
            i += 1
            value_parts: list[str] = []

            while i < length:
                if query[i] == "\\" and i + 1 < length:
                    value_parts.append(query[i:i + 2])
                    i += 2
                elif query[i] == "'":
                    if i + 1 < length and query[i + 1] == "'":
                        value_parts.append("'")
                        i += 2
                    else:
                        break
                else:
                    value_parts.append(query[i])
                    i += 1

            if i >= length:
                return False, "MALFORMED_QUERY"

            literals.append("".join(value_parts))
            normalized_parts.append(f" __str_{len(literals) - 1}__ ")
            i += 1
            continue

        # Quoted identifiers.
        if char in ('"', "`", "["):
            closing = "]" if char == "[" else char
            i += 1

            while i < length:
                if query[i] == closing:
                    if i + 1 < length and query[i + 1] == closing:
                        i += 2
                    else:
                        break
                else:
                    i += 1

            if i >= length:
                return False, "MALFORMED_QUERY"

            normalized_parts.append(" __identifier__ ")
            i += 1
            continue

        normalized_parts.append(char)
        i += 1

    sql = " ".join("".join(normalized_parts).lower().split())

    if re.search(r"\bunion\s+(?:all\s+)?select\b", sql):
        return False, "UNION_EXFILTRATION"

    if re.search(
        r"\bpg_sleep\s*\(|\bwaitfor\s+delay\b|\bbenchmark\s*\(",
        sql,
    ):
        return False, "TIME_BASED_EXECUTION"

    if re.search(
        r";\s*(?:drop\s+table|delete\s+from|exec(?:ute)?\s+(?:xp_cmdshell\b|\w+))",
        sql,
    ):
        return False, "STACKED_QUERY"

    if re.search(r"\bor\s+(?:true|1)\b", sql):
        return False, "BOOLEAN_TAUTOLOGY"

    value_pattern = (
        r"(?:(__str_(\d+)__)|"
        r"([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?))"
    )
    tautology_pattern = re.compile(
        rf"\bor\s+{value_pattern}\s*=\s*{value_pattern}"
    )

    for match in tautology_pattern.finditer(sql):
        left_string_index = match.group(2)
        left_number = match.group(3)
        right_string_index = match.group(5)
        right_number = match.group(6)

        if left_string_index is not None and right_string_index is not None:
            if literals[int(left_string_index)] == literals[int(right_string_index)]:
                return False, "BOOLEAN_TAUTOLOGY"

        elif left_number is not None and right_number is not None:
            try:
                if Decimal(left_number) == Decimal(right_number):
                    return False, "BOOLEAN_TAUTOLOGY"
            except InvalidOperation:
                pass

    return True, "SAFE"
