import threading


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if max_connections < 1:
            raise ValueError("max_connections must be at least 1")
        if ping_timeout <= 0:
            raise ValueError("ping_timeout must be positive")

        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()
        self._closed = False
        self._next_id = 1
        self._available = [self._create_connection() for _ in range(max_connections)]
        self._leased = {}

    def _create_connection(self) -> dict:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if self._closed or not self._available:
                raise RuntimeError("Pool exhausted")

            conn = self._available.pop()

            if not conn["alive"]:
                conn = self._create_connection()

            self._leased[conn["id"]] = conn
            return conn

    def release(self, conn: dict) -> None:
        with self._lock:
            conn_id = conn.get("id")
            leased_conn = self._leased.pop(conn_id, None)

            if leased_conn is None:
                raise ValueError("Connection was not acquired from this pool")

            if not self._closed:
                self._available.append(leased_conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            if self._closed:
                return 0

            healed = 0
            for index, conn in enumerate(self._available):
                if not conn["alive"]:
                    self._available[index] = self._create_connection()
                    healed += 1

            return healed

    def close_all(self) -> None:
        with self._lock:
            self._closed = True

            for conn in self._available:
                conn["alive"] = False
            for conn in self._leased.values():
                conn["alive"] = False

            self._available.clear()
            self._leased.clear()
