def prune_dead_code_and_imports(source_code: str) -> str:
    import ast

    tree = ast.parse(source_code)

    def loaded_names(module: ast.Module) -> set[str]:
        return {
            node.id
            for node in ast.walk(module)
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
        }

    # Remove dead top-level private functions until no further functions qualify.
    while True:
        referenced = loaded_names(tree)
        original_body = tree.body
        tree.body = [
            node
            for node in tree.body
            if not (
                isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                and node.name.startswith("_")
                and node.name not in referenced
            )
        ]
        if len(tree.body) == len(original_body):
            break

    referenced = loaded_names(tree)
    new_body = []

    for node in tree.body:
        if isinstance(node, ast.Import):
            kept_aliases = []
            for alias in node.names:
                bound_name = alias.asname or alias.name.split(".")[0]
                if bound_name in referenced:
                    kept_aliases.append(alias)

            if kept_aliases:
                node.names = kept_aliases
                new_body.append(node)

        elif isinstance(node, ast.ImportFrom):
            # Future imports affect parsing/runtime semantics and should remain.
            if node.module == "__future__" or any(
                alias.name == "*" for alias in node.names
            ):
                new_body.append(node)
                continue

            kept_aliases = [
                alias
                for alias in node.names
                if (alias.asname or alias.name) in referenced
            ]

            if kept_aliases:
                node.names = kept_aliases
                new_body.append(node)

        else:
            new_body.append(node)

    tree.body = new_body
    ast.fix_missing_locations(tree)

    result = ast.unparse(tree)
    compile(result, "<pruned_code>", "exec")
    return result
