from collections import OrderedDict
from threading import RLock
from time import monotonic
from typing import Any, Optional


class TimeBoundedLRUCache:
    def __init__(
        self,
        capacity: int,
        default_ttl_seconds: float = 60.0,
    ) -> None:
        if not isinstance(capacity, int) or isinstance(capacity, bool):
            raise TypeError("capacity must be an integer")
        if capacity <= 0:
            raise ValueError("capacity must be greater than zero")
        if default_ttl_seconds != default_ttl_seconds:
            raise ValueError("default_ttl_seconds cannot be NaN")

        self._capacity = capacity
        self._default_ttl_seconds = default_ttl_seconds
        self._items: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self._lock = RLock()

    def set(
        self,
        key: str,
        value: Any,
        ttl: Optional[float] = None,
    ) -> None:
        with self._lock:
            ttl_seconds = (
                self._default_ttl_seconds if ttl is None else ttl
            )

            if ttl_seconds != ttl_seconds:
                raise ValueError("ttl cannot be NaN")

            expires_at = monotonic() + ttl_seconds

            if key in self._items:
                del self._items[key]
            elif len(self._items) >= self._capacity:
                self._evict_one()

            self._items[key] = (value, expires_at)

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            item = self._items.get(key)

            if item is None:
                return None

            value, expires_at = item

            if expires_at <= monotonic():
                del self._items[key]
                return None

            self._items.move_to_end(key)
            return value

    def delete(self, key: str) -> bool:
        with self._lock:
            if key not in self._items:
                return False

            del self._items[key]
            return True

    def cleanup_expired(self) -> int:
        with self._lock:
            now = monotonic()
            expired_keys = [
                key
                for key, (_, expires_at) in self._items.items()
                if expires_at <= now
            ]

            for key in expired_keys:
                del self._items[key]

            return len(expired_keys)

    def size(self) -> int:
        with self._lock:
            now = monotonic()
            return sum(
                1
                for _, expires_at in self._items.values()
                if expires_at > now
            )

    def _evict_one(self) -> None:
        now = monotonic()

        expired_items = [
            (key, expires_at)
            for key, (_, expires_at) in self._items.items()
            if expires_at <= now
        ]

        if expired_items:
            oldest_expired_key = min(
                expired_items,
                key=lambda item: item[1],
            )[0]
            del self._items[oldest_expired_key]
            return

        self._items.popitem(last=False)
