from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        if len(node_ids) != len(set(node_ids)):
            raise ValueError("node_ids must be unique")

        self.node_ids = list(node_ids)
        self._node_set = set(node_ids)
        self.node_count = len(node_ids)
        self.quorum_threshold = self.node_count // 2 + 1

        self._state: dict[str, dict[str, Any]] = {
            node_id: {} for node_id in self.node_ids
        }
        self._partitions: dict[str, set[str]] = {
            node_id: set(self.node_ids) for node_id in self.node_ids
        }

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        group_a_set = set(group_a)
        group_b_set = set(group_b)

        if len(group_a_set) != len(group_a) or len(group_b_set) != len(group_b):
            raise ValueError("Partition groups must not contain duplicates")

        if not group_a_set or not group_b_set:
            raise ValueError("Partition groups must not be empty")

        if group_a_set & group_b_set:
            raise ValueError("Partition groups must be disjoint")

        if group_a_set | group_b_set != self._node_set:
            raise ValueError("Partition groups must contain all cluster nodes")

        for node_id in group_a_set:
            self._partitions[node_id] = set(group_a_set)

        for node_id in group_b_set:
            self._partitions[node_id] = set(group_b_set)

    def heal_partition(self) -> None:
        if not self.node_ids:
            return

        largest_partition = max(
            (set(nodes) for nodes in self._partitions.values()),
            key=len,
        )
        source_node = next(iter(largest_partition))
        committed_state = dict(self._state[source_node])

        for node_id in self.node_ids:
            self._state[node_id] = dict(committed_state)
            self._partitions[node_id] = set(self.node_ids)

    def propose_write(
        self,
        from_node: str,
        key: str,
        value: Any,
    ) -> bool:
        if from_node not in self._node_set:
            raise ValueError(f"Unknown node: {from_node}")

        active_partition = self._partitions[from_node]

        if len(active_partition) < self.quorum_threshold:
            return False

        for node_id in active_partition:
            self._state[node_id][key] = value

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self._node_set:
            raise ValueError(f"Unknown node: {from_node}")

        return self._state[from_node].get(key)
