import struct
import zlib


class BinaryFrameParser:
    MAGIC = b"\x53\x58"
    HEADER_SIZE = 8
    CRC_SIZE = 4

    def __init__(self, max_payload_length: int | None = None) -> None:
        if max_payload_length is not None and max_payload_length < 0:
            raise ValueError("max_payload_length must be non-negative or None")

        self.max_payload_length = max_payload_length
        self._buffer = bytearray()

    def feed(self, data: bytes) -> list[tuple[int, bytes]]:
        if data:
            self._buffer.extend(data)

        packets: list[tuple[int, bytes]] = []

        while True:
            magic_index = self._buffer.find(self.MAGIC)

            if magic_index < 0:
                self._retain_possible_magic_prefix()
                break

            if magic_index > 0:
                del self._buffer[:magic_index]

            if len(self._buffer) < self.HEADER_SIZE:
                break

            type_bytes = bytes(self._buffer[2:4])
            length_bytes = bytes(self._buffer[4:8])
            msg_type = struct.unpack(">H", type_bytes)[0]
            payload_length = struct.unpack(">I", length_bytes)[0]

            if (
                self.max_payload_length is not None
                and payload_length > self.max_payload_length
            ):
                self._resync()
                continue

            frame_size = self.HEADER_SIZE + payload_length + self.CRC_SIZE

            if len(self._buffer) < frame_size:
                break

            payload_start = self.HEADER_SIZE
            payload_end = payload_start + payload_length
            payload = bytes(self._buffer[payload_start:payload_end])

            received_crc = struct.unpack(
                ">I", self._buffer[payload_end:frame_size]
            )[0]
            calculated_crc = (
                zlib.crc32(type_bytes + length_bytes + payload) & 0xFFFFFFFF
            )

            if received_crc == calculated_crc:
                packets.append((msg_type, payload))
                del self._buffer[:frame_size]
            else:
                self._resync()

        return packets

    def _resync(self) -> None:
        next_magic = self._buffer.find(self.MAGIC, 1)

        if next_magic >= 0:
            del self._buffer[:next_magic]
        else:
            self._retain_possible_magic_prefix()

    def _retain_possible_magic_prefix(self) -> None:
        if self._buffer.endswith(self.MAGIC[:1]):
            self._buffer[:] = self._buffer[-1:]
        else:
            self._buffer.clear()
