import re

MARKDOWN_LINK_REGEX = re.compile(
    r"\[([A-Za-z0-9_\s]+)\]\((https?://[^\s)]+)\)"
)

def parse_markdown_links(text: str) -> list[dict[str, str]]:
    """
    Extract markdown links in the form [title](https://example.com).

    The pattern uses no nested quantifiers, preventing polynomial or
    exponential regex backtracking.
    """
    return [
        {"title": match.group(1), "url": match.group(2)}
        for match in MARKDOWN_LINK_REGEX.finditer(text)
    ]
