from collections import deque
from threading import RLock
from numbers import Real


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if not isinstance(max_connections, int) or isinstance(max_connections, bool):
            raise TypeError("max_connections must be an integer")
        if max_connections <= 0:
            raise ValueError("max_connections must be greater than zero")
        if not isinstance(ping_timeout, Real) or ping_timeout < 0:
            raise ValueError("ping_timeout must be a non-negative number")

        self.max_connections = max_connections
        self.ping_timeout = float(ping_timeout)

        self._lock = RLock()
        self._next_id = 1
        self._connections = {}
        self._available = deque()
        self._in_use = {}
        self._closed = False

        for _ in range(max_connections):
            connection = self._create_connection()
            self._connections[connection["id"]] = connection
            self._available.append(connection)

    def _create_connection(self) -> dict:
        connection = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return connection

    def acquire(self) -> dict:
        with self._lock:
            if self._closed or not self._available:
                raise RuntimeError("Pool exhausted")

            connection = self._available.popleft()
            self._in_use[connection["id"]] = connection
            return connection

    def release(self, conn: dict) -> None:
        with self._lock:
            if self._closed:
                raise RuntimeError("Pool is closed")
            if not isinstance(conn, dict):
                raise TypeError("conn must be a dictionary")

            conn_id = conn.get("id")
            tracked = self._in_use.get(conn_id)

            if tracked is not conn:
                raise ValueError("Connection is not currently acquired")

            del self._in_use[conn_id]
            self._available.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            healed = 0

            for connection_id, connection in list(self._connections.items()):
                if connection.get("alive") is False:
                    replacement = self._create_connection()

                    del self._connections[connection_id]
                    self._connections[replacement["id"]] = replacement

                    if connection_id in self._in_use:
                        del self._in_use[connection_id]
                        self._in_use[replacement["id"]] = replacement
                    else:
                        self._available = deque(
                            replacement if item is connection else item
                            for item in self._available
                        )

                    healed += 1

            return healed

    def close_all(self) -> None:
        with self._lock:
            for connection in self._connections.values():
                connection["alive"] = False

            self._available.clear()
            self._in_use.clear()
            self._connections.clear()
            self._closed = True
