import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    def load_names(node):
        return {
            child.id
            for child in ast.walk(node)
            if isinstance(child, ast.Name) and isinstance(child.ctx, ast.Load)
        }

    used_names = load_names(tree)

    tree.body = [
        node
        for node in tree.body
        if not (
            isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name.startswith("_")
            and node.name not in used_names
        )
    ]

    used_names = load_names(tree)
    new_body = []

    for node in tree.body:
        if isinstance(node, ast.Import):
            kept = [
                alias
                for alias in node.names
                if (alias.asname or alias.name.split(".", 1)[0]) in used_names
            ]
            if kept:
                node.names = kept
                new_body.append(node)

        elif isinstance(node, ast.ImportFrom):
            if node.module == "__future__":
                new_body.append(node)
                continue

            kept = [
                alias
                for alias in node.names
                if alias.name == "*"
                or (alias.asname or alias.name) in used_names
            ]
            if kept:
                node.names = kept
                new_body.append(node)

        else:
            new_body.append(node)

    tree.body = new_body
    return ast.unparse(tree)
